"""Arithmetic helpers."""


def add(a, b):
    return a + b


def subtract(a, b):
    return a - b


def multiply(a, b):
    """Return a * b."""
    return a * b


def divide(a, b):
    """Return a / b as a float.

    Raises ZeroDivisionError with the message "cannot divide by zero" when b == 0.
    """
    if b == 0:
        raise ZeroDivisionError("cannot divide by zero")
    return a / b
